Json.query:
query UploadPageProductQuery($id: ID!, $useResourceCatalog: Boolean) {
  products(ids: [$id], useResourceCatalog: $useResourceCatalog) {
    name
    copyrightInfringement {
      name
      __typename
    }
    description
    isFree
    price
    discountprice
    licenseprice
    teachingDuration
    answerKey
    statusUser
    status
    filePreview {
      pageCount
      previewUrl
      __typename
    }
    copyrightDeclaration
    itemType
    commonCoreStandards {
      name
      id: sphinxId
      parentIds
      __typename
    }
    taxonomyTags {
      id
      __typename
    }
    categories {
      id
      name
      __typename
    }
    localization {
      countryId
      countryIdFlag
      country {
        name
        __typename
      }
      __typename
    }
    audience
    audienceText
    videoType
    videoTypeText
    taxCode {
      id
      __typename
    }
    author {
      id
      __typename
    }
    __typename
  }
}
